import React, { useState } from 'react';

const QuizPage = () => {
  const [formData, setFormData] = useState({
    subject: '',
    examType: '',
    classYear: '',
    topics: [],
    difficultyLevels: [],
    customTimeLimits: {},
    quizMode: '',
    addHints: false,
    adaptiveDifficulty: false,
    answerExplanation: false,
    questionSource: '',
    examMode: false,
    breakIntoSubtopics: false,
    studentName: '',
    randomizeOrder: false,
    allowRetry: false,
  });

  // Handle changes for different inputs
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleMultiChange = (e) => {
    const { value, checked } = e.target;
    if (checked) {
      setFormData((prevData) => ({
        ...prevData,
        topics: [...prevData.topics, value],
      }));
    } else {
      setFormData((prevData) => ({
        ...prevData,
        topics: prevData.topics.filter((topic) => topic !== value),
      }));
    }
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleTimeLimitChange = (e, topic) => {
    setFormData((prevData) => ({
      ...prevData,
      customTimeLimits: {
        ...prevData.customTimeLimits,
        [topic]: e.target.value,
      },
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle form submission (e.g., send data to backend)
    console.log(formData);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto bg-white shadow-md rounded-lg">
      <h2 className="text-2xl font-bold mb-6">Quiz Configuration</h2>

      <form onSubmit={handleSubmit}>
        {/* Subject Selection */}
        <div className="mb-4">
          <label className="block font-semibold">Subject</label>
          <select
            name="subject"
            value={formData.subject}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Subject</option>
            <option value="Mathematics">Mathematics</option>
            <option value="Physics">Physics</option>
            <option value="Chemistry">Chemistry</option>
            <option value="Biology">Biology</option>
            <option value="Computer Science">Computer Science</option>
            {/* Add more subjects here */}
          </select>
        </div>

        {/* Exam Type */}
        <div className="mb-4">
          <label className="block font-semibold">Exam Type</label>
          <select
            name="examType"
            value={formData.examType}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Exam Type</option>
            <option value="Midterm">Midterm</option>
            <option value="Final Exam">Final Exam</option>
            <option value="Mock Test">Mock Test</option>
            <option value="Certification Exam">Certification Exam</option>
            {/* Add more exam types here */}
          </select>
        </div>

        {/* Class Year */}
        <div className="mb-4">
          <label className="block font-semibold">Class/Year</label>
          <input
            type="text"
            name="classYear"
            value={formData.classYear}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
            placeholder="e.g. 1st Year, 2nd Year"
          />
        </div>

        {/* Topics Selection */}
        <div className="mb-4">
          <label className="block font-semibold">Topics</label>
          <div>
            <label>
              <input
                type="checkbox"
                value="Algebra"
                checked={formData.topics.includes('Algebra')}
                onChange={handleMultiChange}
              />
              Algebra
            </label>
            <label>
              <input
                type="checkbox"
                value="Calculus"
                checked={formData.topics.includes('Calculus')}
                onChange={handleMultiChange}
              />
              Calculus
            </label>
            <label>
              <input
                type="checkbox"
                value="Mechanics"
                checked={formData.topics.includes('Mechanics')}
                onChange={handleMultiChange}
              />
              Mechanics
            </label>
            {/* Add more topics dynamically based on subject selection */}
          </div>
        </div>

        {/* Difficulty Level Selection */}
        <div className="mb-4">
          <label className="block font-semibold">Select Difficulty Levels</label>
          <div>
            <label>
              <input
                type="checkbox"
                value="Easy"
                checked={formData.difficultyLevels.includes('Easy')}
                onChange={handleDifficultyChange}
              />
              Easy
            </label>
            <label>
              <input
                type="checkbox"
                value="Medium"
                checked={formData.difficultyLevels.includes('Medium')}
                onChange={handleDifficultyChange}
              />
              Medium
            </label>
            <label>
              <input
                type="checkbox"
                value="Hard"
                checked={formData.difficultyLevels.includes('Hard')}
                onChange={handleDifficultyChange}
              />
              Hard
            </label>
          </div>
        </div>

        {/* Custom Time Limit */}
        <div className="mb-4">
          <label className="block font-semibold">Custom Time Limits (per topic)</label>
          {formData.topics.map((topic) => (
            <div key={topic}>
              <label>{topic}</label>
              <input
                type="number"
                value={formData.customTimeLimits[topic] || ''}
                onChange={(e) => handleTimeLimitChange(e, topic)}
                className="w-full p-2 border border-gray-300 rounded"
                placeholder="Enter time in minutes"
              />
            </div>
          ))}
        </div>

        {/* Additional Quiz Features */}
        <div className="mb-4">
          <label className="block font-semibold">Quiz Features</label>
          <div className="flex space-x-4">
            <label>
              <input
                type="checkbox"
                name="addHints"
                checked={formData.addHints}
                onChange={handleChange}
              />
              Add Hints
            </label>
            <label>
              <input
                type="checkbox"
                name="adaptiveDifficulty"
                checked={formData.adaptiveDifficulty}
                onChange={handleChange}
              />
              Adaptive Difficulty
            </label>
            <label>
              <input
                type="checkbox"
                name="answerExplanation"
                checked={formData.answerExplanation}
                onChange={handleChange}
              />
              Include Answer Explanation
            </label>
            <label>
              <input
                type="checkbox"
                name="examMode"
                checked={formData.examMode}
                onChange={handleChange}
              />
              Exam Mode
            </label>
            <label>
              <input
                type="checkbox"
                name="breakIntoSubtopics"
                checked={formData.breakIntoSubtopics}
                onChange={handleChange}
              />
              Break Into Subtopics
            </label>
            <label>
              <input
                type="checkbox"
                name="randomizeOrder"
                checked={formData.randomizeOrder}
                onChange={handleChange}
              />
              Randomize Question Order
            </label>
          </div>
        </div>

        {/* Student Name */}
        <div className="mb-4">
          <label className="block font-semibold">Student Name</label>
          <input
            type="text"
            name="studentName"
            value={formData.studentName}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
            placeholder="Enter your name"
          />
        </div>

        {/* Submit Button */}
        <div className="mb-4 text-center">
          <button type="submit" className="bg-blue-600 text-white py-2 px-4 rounded-lg">
            Create Quiz
          </button>
        </div>
      </form>
    </div>
  );
};

export default QuizPage;
